    for row in csv.DictReader(f):
        cat[row['point_uri']] = row

txt = open(GRAPH_TTL).read()
# point -> tsref
pairs = re.findall(r'(?:bldg:|<[^>]+>)([A-Za-z0-9_.]+)\s+[^.;]*?ref:hasExternalReference\s*<urn:[^:]+:tsref:([0-9a-f-]+)>', txt)
# better: parse line by line
point_to_ts = {}
for point_uri, tsid in re.findall(r'bldg:([\w.]+)\s+a[^;]*?;.*?ref:hasExternalReference\s*<urn:[\w-]+:tsref:([0-9a-f-]+)>', txt, re.S):
    point_to_ts[point_uri] = tsid
print("found", len(point_to_ts))
# Actually do a robust scan: find each bldg:X ... ref:hasExternalReference <...tsref:ID>
for m in re.finditer(r'bldg:([\w.]+)[^;]*?;[^\n]*?\n(?:\s+[^.;\n]*?;\n)*?\s+ref:hasExternalReference\s*<urn:[\w-]+:tsref:([0-9a-f-]+)>', txt):
    pass
# Simpler: split on "bldg:" and find first hasExternalReference after
items = txt.split('bldg:')
point_to_ts = {}
for it in items[1:]:
    name = it.split()[0].rstrip(' .')
    m = re.search(r'ref:hasExternalReference\s*<urn:[\w-]+:tsref:([0-9a-f-]+)>', it)
    if m:
        point_to_ts[name] = m.group(1)
print("points with ts:", len(point_to_ts))
zones = ["Zone_F1_Z01","Zone_F2_Z01","Zone_F2_Z02","Zone_F2_Z03","Zone_F2_Z04","Zone_F2_Z05","Zone_F3_Z01","Zone_F3_Z02","Zone_F3_Z03","Zone_F3_Z04","Zone_F3_Z05","Zone_F4_Z01","Zone_F4_Z02","Zone_F4_Z03","Zone_F4_Z04","Zone_F4_Z05"]
for z in zones:
    point = z + ".Zone_Air_Temperature_Sensor"
    tid = point_to_ts.get(point)
    if tid in cat:
        c = cat[tid]
        print(z, tid, c['point_class'], c['quantity_kind'], c['unit'])
    else:
        print(z, tid, "NOT FOUND" if tid is None else "TS NOT IN CATALOG")

